// How each trade's home lays out the day, platform-free (websites and apps): a repair pipeline, a visit timeline, an appointment book, a task list.

const istDay = (d) => new Date(new Date(d).getTime() + 330 * 60000).toISOString().slice(0, 10);
const istHour = (d) => new Date(new Date(d).getTime() + 330 * 60000).getUTCHours();

// Workshop: what needs the owner, what is being worked on, what waits on the customer.
export function workshopColumns(jobs = []) {
  const cols = { you: [], work: [], customer: [] };
  for (const j of jobs) {
    if (j.attention || !j.workerId) cols.you.push(j);
    else if (/waiting on customer|quote sent/i.test(j.status || '')) cols.customer.push(j);
    else cols.work.push(j);
  }
  return [
    { key: 'you', label: 'Needs you', items: cols.you },
    { key: 'work', label: 'In progress', items: cols.work },
    { key: 'customer', label: 'Waiting on customer', items: cols.customer },
  ];
}

// Visits and tasks: today's jobs and plan visits in time order, each marked past or upcoming against now.
export function todaysTimeline(jobs = [], visits = [], now = new Date()) {
  const today = istDay(now);
  const rows = [
    ...jobs.filter((j) => j.at && istDay(j.at) === today).map((j) => ({ id: `${j.kind}-${j.id}`, at: j.at, title: j.title, sub: j.subtitle, status: j.status, attention: !!j.attention, to: j.to })),
    ...visits.filter((v) => v.day === today && v.status !== 'cancelled').map((v) => ({ id: `plan-${v._id}`, at: v.at, title: v.plan || 'Plan visit', sub: v.address, status: v.status === 'scheduled' ? 'Plan visit' : v.status, attention: false, to: '/shop/plans' })),
  ].sort((a, b) => new Date(a.at) - new Date(b.at));
  const t = now.getTime();
  return rows.map((r) => ({ ...r, past: new Date(r.at).getTime() < t - 30 * 60000 }));
}

// Appointments: today's bookings by hour across the working day, so free hours show as gaps.
export function hourBook(rows = [], from = 8, to = 21) {
  const book = [];
  for (let h = from; h <= to; h++) book.push({ hour: h, label: `${h % 12 || 12} ${h < 12 ? 'AM' : 'PM'}`, items: rows.filter((r) => istHour(r.at) === h) });
  const early = rows.filter((r) => istHour(r.at) < from); const late = rows.filter((r) => istHour(r.at) > to);
  if (early.length) book[0].items.unshift(...early);
  if (late.length) book[book.length - 1].items.push(...late);
  return book;
}

export const timeOf = (d) => new Date(d).toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit', timeZone: 'Asia/Kolkata' });
